const jobId = $json.jobId;
const code = $json.code || 'E_INTERNAL_JOB_FAILED';
const message = $json.message || 'Workflow reported a failure';
return [{ json: { path: '/api/v1/internal/jobs/result', body: { jobId, code, message } } }];

const crypto = require('crypto');
const secret = $env.INTERNAL_API_SECRET;
const path = $json.path;
const body = $json.body || {};
const method = 'POST';
const stable = (v) => {
  if (Array.isArray(v)) return '[' + v.map(stable).join(',') + ']';
  if (v && typeof v === 'object') {
    return '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + stable(v[k])).join(',') + '}';
  }
  return JSON.stringify(v);
};
const canonicalBody = Object.keys(body).length > 0 ? stable(body) : '';
const timestamp = Math.floor(Date.now()/1000).toString();
const requestId = crypto.randomUUID();
const canonical = [method, path, timestamp, requestId, canonicalBody].join('\n');
const signature = crypto.createHmac('sha256', secret).update(canonical).digest('hex');
return [{ json: { path, body, headers: { 'X-Signature': signature, 'X-Timestamp': timestamp, 'X-Request-Id': requestId, 'Content-Type': 'application/json' } } }];
